def subject_name_to_key(subject_type: str, name: str) -> SubjectPseudoKey:
    prefix = '/subjects/'
    if subject_type != 'subject':
        prefix += f'{subject_type}:'
    return prefix + re_subject.sub("_", name.lower()).strip("_")


